    { x: 1750, y: 300 }, { x: 1750, y: 2000 }, { x: 950, y: 1350 }, { x: 2550, y: 1350 },
    { x: 550, y: 1750 }, { x: 2550, y: 550 },
  ];
  for (const spot of spots) hiddenPackages.push({ ...spot, found: false });

