export function completeMission(state, player, audio) {
  const mission = currentMission(state);
  if (!mission) return 0;
  player.cash += mission.reward;
  state.completed.push(mission.id);
  state.index += 1;
  state.active = false;
  state.step = 0;
  state.timer = 0;
  state.grabTimer = 0;
