  }

  function drawPerson(cam, x, y, angle, skin, shirt, flash) {
    ctx.save();
    ctx.translate(x - cam.x, y - cam.y);
    ctx.rotate(angle);
    ctx.fillStyle = 'rgba(0,0,0,0.3)';
    ctx.beginPath();
    ctx.ellipse(2, 3, 12, 9, 0, 0, Math.PI * 2);
    ctx.fill();
