    if (game.taxiCustomer) {
      const c = game.taxiCustomer;
      ctx.fillStyle = '#3d7bfd';
      ctx.font = `700 13px ${FONT}`;
      ctx.textAlign = 'center';
      ctx.fillText('TAXI!', c.x - cam.x, c.y - 22 - cam.y);
