      ctx.strokeStyle = 'rgba(255, 255, 255, 0.9)';
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.arc(player.x - cam.x, player.y - cam.y, 17, 0, Math.PI * 2);
      ctx.stroke();
